script:
frappe.ui.form.on('Customer', {
    refresh(frm) {

        if (!frm.doc.name || frm.is_new()) {
            return;
        }

        // Clear previous headline alerts & indicateurs spécifiques
        frm.dashboard.clear_headline();
        $('.form-dashboard-section .row .indicator:contains("Facturation Annuelle")').remove();
        $('.form-dashboard-section .row .indicator:contains("Total des Impayés")').remove();

        // Buffers HTML pour tout afficher dans UN seul headline
        let rendezVousHtml = "";
        let ristourneHtml  = "";
        let verifHtml      = "";

        function update_headline() {
            if (!rendezVousHtml && !ristourneHtml && !verifHtml) return;

            const full_html = `
                <div>
                    ${verifHtml      || ""}
                    ${rendezVousHtml || ""}
                    ${ristourneHtml  || ""}
                </div>
            `;
            frm.dashboard.set_headline_alert(full_html, 'blue');
        }

        // Helpers numériques
        function num(v) {
            try {
                if (typeof flt === "function") {
                    return flt(v || 0);
                }
            } catch(e) {}
            const n = parseFloat(v || 0);
            return isNaN(n) ? 0 : n;
        }

        function almostEqual(a, b, tolerance = 50) {
            // Si les deux valeurs sont à zéro, considérer comme égales
            if (a === 0 && b === 0) return true;
            // Tolérance de 50 dinars par défaut
            return Math.abs(a - b) <= tolerance;
        }

        // --- 1) CALL EXISTANT : get_customer_info ---
        frappe.call({
            method: "get_customer_info",
            args: {
                customer_name: frm.doc.name
            },
            callback: function(r) {
                if (r.result) {
                    let final_result = r.result[0] || {};
                    let rendez_vous = r.result[1] || [];
                    let heatmapData = r.result[2];

                    // Indicateurs principaux
                    frm.dashboard.clear_headline();
                    frm.dashboard.add_indicator(
                        `Total des ventes: ${final_result['Total des ventes']} د.ت`,
                        'blue'
                    );
                    frm.dashboard.add_indicator(
                        `Total des paiements: ${final_result['Total des paiements']} د.ت`,
                        'green'
                    );

                    // --- Tous les types de paiement + remises + retenues + avances ---

                    if (final_result['Total des paiements en Espèces']) {
                        frm.dashboard.add_indicator(
                            `Paiements en Espèces: ${final_result['Total des paiements en Espèces']} د.ت`,
                            'orange'
                        );
                    }

                    if (final_result['Total des paiements par Virement']) {
                        frm.dashboard.add_indicator(
                            `Paiements par Virement: ${final_result['Total des paiements par Virement']} د.ت`,
                            'orange'
                        );
                    }

                    if (final_result['Total des paiements par Chèques encaissé']) {
                        frm.dashboard.add_indicator(
                            `Chèques encaissés: ${final_result['Total des paiements par Chèques encaissé']} د.ت`,
                            'purple'
                        );
                    }

                    if (final_result['Total des paiements par Chèques non encaissé']) {
                        frm.dashboard.add_indicator(
                            `Chèques non encaissés: ${final_result['Total des paiements par Chèques non encaissé']} د.ت`,
                            'red'
                        );
                    }

                    if (final_result['Total des paiements par Chèques sans provision']) {
                        frm.dashboard.add_indicator(
                            `Chèques sans provision: ${final_result['Total des paiements par Chèques sans provision']} د.ت`,
                            'brown'
                        );
                    }

                    if (final_result['Total des paiements par Traite Bancaire']) {
                        frm.dashboard.add_indicator(
                            `Traites bancaires: ${final_result['Total des paiements par Traite Bancaire']} د.ت`,
                            'cyan'
                        );
                    }

                    if (final_result['Total des retenues à la source']) {
                        frm.dashboard.add_indicator(
                            `Retenues à la source: ${final_result['Total des retenues à la source']} د.ت`,
                            'yellow'
                        );
                    }

                    if (final_result['Total des avances du client']) {
                        frm.dashboard.add_indicator(
                            `Avances du client: ${final_result['Total des avances du client']} د.ت`,
                            'yellow'
                        );
                    }

                    if (final_result['Total des remises sur commande']) {
                        frm.dashboard.add_indicator(
                            `Remises sur commande: ${final_result['Total des remises sur commande']} د.ت`,
                            'purple'
                        );
                    }

                    if (final_result['Total des dettes non payées']) {
                        frm.dashboard.add_indicator(
                            `Dettes non payées: ${final_result['Total des dettes non payées']} د.ت`,
                            'gray'
                        );
                    }

                    if (final_result['Total perte de non paiement']) {
                        frm.dashboard.add_indicator(
                            `Perte de non paiement: ${final_result['Total perte de non paiement']} د.ت`,
                            'red'
                        );
                    }

                    // --- Vérifications de cohérence des totaux ---

                    const t = final_result;

                    const totalVentes   = num(t["Total des ventes"]);
                    const totalPayts    = num(t["Total des paiements"]);
                    const totalRemises  = num(t["Total des remises sur commande"]);

                    const especes       = num(t["Total des paiements en Espèces"]);
                    const virement      = num(t["Total des paiements par Virement"]);
                    const chqEnc        = num(t["Total des paiements par Chèques encaissé"]);
                    const chqNon        = num(t["Total des paiements par Chèques non encaissé"]);
                    const chqSP         = num(t["Total des paiements par Chèques sans provision"]);
                    const traite        = num(t["Total des paiements par Traite Bancaire"]);
                    const retenues      = num(t["Total des retenues à la source"]);
                    const dettes        = num(t["Total des dettes non payées"]);
                    const pertes        = num(t["Total perte de non paiement"]);
                    const avancesClient = num(t["Total des avances du client"]);

                    // Tolérance acceptée pour les vérifications
                    const tolerance = 50; // 50 dinars

                    // Règle 1 : Total ventes = Total paiements + remises
                    const lhs1 = totalVentes;
                    const rhs1 = totalPayts + totalRemises;
                    const delta1 = Math.abs(lhs1 - rhs1);
                    const ok1  = almostEqual(lhs1, rhs1, tolerance);

                    // Règle 2 : Total paiements = somme des champs de paiement + dettes/pertes/avances
                    const breakdownSum =
                        especes +
                        virement +
                        chqEnc +
                        chqNon +
                        chqSP +
                        traite +
                        retenues +
                        dettes +
                        pertes +
                        avancesClient;

                    const delta2 = Math.abs(totalPayts - breakdownSum);
                    const ok2 = almostEqual(totalPayts, breakdownSum, tolerance);

                    verifHtml = "";

                    // Ne pas afficher d'alerte si tous les totaux sont à zéro
                    const allZero = (totalVentes === 0 && totalPayts === 0 && totalRemises === 0);

                    if (allZero) {
                        verifHtml = ""; // Pas d'alerte si tout est à zéro
                    } else if (!ok1 || !ok2) {
                        // 🔴 Cas incohérent : bloc rouge
                        verifHtml += `
                            <div style="
                                margin-bottom:8px;
                                padding:6px 8px;
                                border-radius:3px;
                                background:#fff1f0;
                                border:1px solid #ffa39e;
                                font-size:11px;
                                color:#a8071a;
                            ">
                                <b>⚠ Incohérence dans les totaux client :</b><br>
                                <small style="color:#8c8c8c;">(Tolérance acceptée : ${frappe.format(tolerance, {fieldtype:"Currency"})})</small><br>
                        `;

                        if (!ok1) {
                            verifHtml += `
                                • Total des ventes (${frappe.format(lhs1, {fieldtype:"Currency"})})
                                  ≠ Total des paiements + remises
                                  (${frappe.format(rhs1, {fieldtype:"Currency"})})<br>
                                  <small style="color:#cf1322;">→ Écart: ${frappe.format(delta1, {fieldtype:"Currency"})}</small><br>
                            `;
                        }

                        if (!ok2) {
                            verifHtml += `
                                • Total des paiements (${frappe.format(totalPayts, {fieldtype:"Currency"})})
                                  ≠ Somme des modes de paiement, dettes, pertes et avances
                                  (${frappe.format(breakdownSum, {fieldtype:"Currency"})})<br>
                                  <small style="color:#cf1322;">→ Écart: ${frappe.format(delta2, {fieldtype:"Currency"})}</small><br>
                            `;
                        }

                        verifHtml += `</div>`;
                    } else {
                        // ✅ Cas OK : bloc vert
                        verifHtml = `
                            <div style="
                                margin-bottom:8px;
                                padding:6px 8px;
                                border-radius:3px;
                                background:#f6ffed;
                                border:1px solid #b7eb8f;
                                font-size:11px;
                                color:#135200;
                            ">
                                <b>✓ Totaux cohérents :</b><br>
                                <small style="color:#8c8c8c;">(Tolérance acceptée : ${frappe.format(tolerance, {fieldtype:"Currency"})})</small><br>
                                • Total des ventes = Total des paiements + remises<br>
                                  <small style="color:#52c41a;">→ Écart: ${frappe.format(delta1, {fieldtype:"Currency"})}</small><br>
                                • Total des paiements = somme des modes de paiement, dettes, pertes et avances<br>
                                  <small style="color:#52c41a;">→ Écart: ${frappe.format(delta2, {fieldtype:"Currency"})}</small>
                            </div>
                        `;
                    }

                    // RDV en HTML (block jaune)
                    if (Array.isArray(rendez_vous) && rendez_vous.length > 0) {
                        const rendez_vous_details = rendez_vous.join('<br>');
                        rendezVousHtml = `
                            <div style="
                                margin-bottom:8px;
                                padding:8px;
                                background:#fffbe6;
                                border:1px solid #ffe58f;
                                border-radius:3px;
                                font-size:12px;
                            ">
                                <b>Prochains rendez-vous :</b><br>
                                ${rendez_vous_details}
                            </div>
                        `;
                    }

                    update_headline();

                    if (heatmapData) {
                        frm.dashboard.update_heatmap(heatmapData);
                    }
                }
            }
        });

        // --- 2) NOUVEAU CALL : RISTOURNE ---
        frappe.call({
            method: "customization_app.api.get_customer_ristourne_dashboard",
            args: {
                customer: frm.doc.name
            },
            callback: function(r) {
                if (!r.message) return;

                const current   = r.message.current_ristourne;
                const situation = r.message.ristourne_situation;

                if (current) {
                    const currentYear = new Date().getFullYear();
                    const nextYear    = currentYear + 1;

                    frm.dashboard.add_indicator(
                        `Ristourne ${currentYear} (pour ${nextYear}) : ${frappe.format(current.ristourne, {fieldtype:"Currency"})}`,
                        'green'
                    );

                    ristourneHtml = render_ristourne_dashboard(current, situation);
                    update_headline();
                }
            }
        });
    }
});

// --- FONCTION DE RENDU DU DASHBOARD RISTOURNE ---
function render_ristourne_dashboard(current, situation) {
    if (!current) {
        return `<div style="padding:8px;color:#888;">Aucune donnée de ristourne trouvée.</div>`;
    }

    const currentYear  = new Date().getFullYear();   // N
    const previousYear = currentYear - 1;            // N-1
    const nextYear     = currentYear + 1;            // N+1

    const total_ht_fmt  = frappe.format(current.total_ht,   {fieldtype: "Currency"});
    const ristourne_fmt = frappe.format(current.ristourne, {fieldtype: "Currency"});

    // --- Ventes mensuelles ---
    const monthlyEntries = Object.entries(current.monthly_sales || {}).sort(
        ([aKey], [bKey]) => aKey.localeCompare(bKey)
    );

    let total_ht_from_months = 0;
    const monthlyRows = monthlyEntries.map(([month, value]) => {
        total_ht_from_months += value || 0;
        return `
            <tr>
                <td style="padding:4px 8px;">${month}</td>
                <td style="padding:4px 8px;text-align:right;">
                    ${frappe.format(value, {fieldtype:"Currency"})}
                </td>
            </tr>
        `;
    }).join("");

    const total_ht_from_months_fmt = frappe.format(total_ht_from_months, {fieldtype:"Currency"});

    // --- Paliers ---
    let total_ht_from_paliers = 0;
    let total_ristourne_from_paliers = 0;

    const paliersRows = (current.paliers || []).map(p => {
        total_ht_from_paliers        += p.montant_applique_ht || 0;
        total_ristourne_from_paliers += p.montant_ristourne   || 0;

        const palier_range = `
            ${frappe.format(p.palier_minimum, {fieldtype:"Currency"})}
            → 
            ${frappe.format(p.palier_maximum, {fieldtype:"Currency"})}
        `;
        const montant_applique_fmt  = frappe.format(p.montant_applique_ht, {fieldtype:"Currency"});
        const montant_ristourne_fmt = frappe.format(p.montant_ristourne,   {fieldtype:"Currency"});

        return `
            <tr>
                <td style="padding:4px 8px;">${palier_range}</td>
                <td style="padding:4px 8px;text-align:right;">${p.pourcentage} %</td>
                <td style="padding:4px 8px;text-align:right;">${montant_applique_fmt}</td>
                <td style="padding:4px 8px;text-align:right;">${montant_ristourne_fmt}</td>
            </tr>
        `;
    }).join("");

    const total_ht_from_paliers_fmt        = frappe.format(total_ht_from_paliers,        {fieldtype:"Currency"});
    const total_ristourne_from_paliers_fmt = frappe.format(total_ristourne_from_paliers, {fieldtype:"Currency"});

    // --- Explication calcul ---
    const explication_html = `
        <div style="margin-top:6px;font-size:12px;color:#555;">
            <div>
                • La somme des ventes mensuelles est <b>${total_ht_from_months_fmt}</b>,
                  ce qui correspond au <b>total HT ${currentYear}</b> (${total_ht_fmt}).
            </div>
            <div>
                • Ce montant est réparti par <b>paliers</b>. Pour chaque palier :<br>
                <span style="margin-left:10px;">
                    <i>Montant appliqué HT × Pourcentage = Montant de ristourne</i>
                </span>
            </div>
            <div>
                • La somme des montants de ristourne de tous les paliers est
                  <b>${total_ristourne_from_paliers_fmt}</b>, soit la <b>ristourne cumulée</b> : <b>${ristourne_fmt}</b>.
            </div>
        </div>
    `;

    // --- Bloc N-1 (optionnel) ---
    let n1_block = "";
    if (situation && situation.status !== "NO_ACTIVE") {
        const dispo   = frappe.format(situation.available_to_date || 0, {fieldtype:"Currency"});
        const used    = frappe.format(situation.used_so_far       || 0, {fieldtype:"Currency"});
        const allowed = frappe.format(situation.allowed_to_date   || 0, {fieldtype:"Currency"});

        n1_block = `
            <div style="margin-top:16px;">
                <details>
                    <summary style="cursor:pointer;font-weight:600;margin-bottom:4px;">
                        Ristourne ${previousYear} en cours d'utilisation (${currentYear})
                    </summary>
                    <div style="font-size:12px;color:#555;margin-bottom:4px;">
                        Cette ristourne provient de vos achats de <b>${previousYear}</b>
                        et est consommable sur l'année <b>${currentYear}</b>.
                    </div>
                    <div style="font-size:12px;line-height:1.6;">
                        <div>Autorisé à ce jour : <b>${allowed}</b></div>
                        <div>Déjà utilisé : <b>${used}</b></div>
                        <div>Disponible : <b>${dispo}</b></div>
                    </div>
                </details>
            </div>
        `;
    } else if (situation && situation.note_html) {
        n1_block = `
            <div style="margin-top:16px;">
                ${situation.note_html}
            </div>
        `;
    }

    return `
        <div style="font-size:12px;line-height:1.5;">
            <div style="font-weight:600;margin-bottom:6px;">
                Programme de ristourne ${currentYear} → ${nextYear}
            </div>

            <div style="display:flex;flex-wrap:wrap;gap:24px;margin-bottom:12px;">
                <div>
                    Achats HT ${currentYear} :<br>
                    <b>${total_ht_fmt}</b>
                </div>
                <div>
                    Ristourne cumulée (utilisable en ${nextYear}) :<br>
                    <b>${ristourne_fmt}</b>
                </div>
            </div>

            <details style="margin-bottom:10px;">
                <summary style="cursor:pointer;font-weight:600;margin-bottom:4px;">
                    Détail des ventes mensuelles ${currentYear}
                </summary>
                <table style="width:100%;border-collapse:collapse;border:1px solid #e0e0e0;font-size:11px;background:#fff;margin-top:6px;">
                    <thead>
                        <tr style="background:#f5f5f5;">
                            <th style="padding:4px 8px;text-align:left;">Mois</th>
                            <th style="padding:4px 8px;text-align:right;">Montant HT</th>
                        </tr>
                    </thead>
                    <tbody>
                        ${monthlyRows}
                        <tr style="font-weight:600;background:#fafafa;">
                            <td style="padding:4px 8px;">Total</td>
                            <td style="padding:4px 8px;text-align:right;">${total_ht_from_months_fmt}</td>
                        </tr>
                    </tbody>
                </table>
            </details>

            <details style="margin-bottom:8px;">
                <summary style="cursor:pointer;font-weight:600;margin-bottom:4px;">
                    Détail des paliers de ristourne
                </summary>
                <table style="width:100%;border-collapse:collapse;border:1px solid #e0e0e0;font-size:11px;background:#fff;margin-top:6px;">
                    <thead>
                        <tr style="background:#f5f5f5;">
                            <th style="padding:4px 8px;text-align:left;">Palier HT</th>
                            <th style="padding:4px 8px;text-align:right;">%</th>
                            <th style="padding:4px 8px;text-align:right;">Montant appliqué HT</th>
                            <th style="padding:4px 8px;text-align:right;">Montant ristourne</th>
                        </tr>
                    </thead>
                    <tbody>
                        ${paliersRows}
                        <tr style="font-weight:600;background:#fafafa;">
                            <td style="padding:4px 8px;">Total</td>
                            <td style="padding:4px 8px;text-align:right;">–</td>
                            <td style="padding:4px 8px;text-align:right;">${total_ht_from_paliers_fmt}</td>
                            <td style="padding:4px 8px;text-align:right;">${total_ristourne_from_paliers_fmt}</td>
                        </tr>
                    </tbody>
                </table>
            </details>

            
            ${n1_block}
        </div>
    `;
}

console.log("Client Script for Compagne SMS loaded ✅");

// --- Helper: update counters from message field ---
function update_message_counters(frm) {
    const txt = frm.doc.message || "";

    // nombre de caractères
    frm.doc.total_des_charactères = txt.length;
    // nombre de SMS (segments de 160 caractères)
    frm.doc.total_message_s = txt ? Math.ceil(txt.length / 160) : 0;

    frm.refresh_field('total_des_charactères');
    frm.refresh_field('total_message_s');
}

// Petite fonction utilitaire commune
function run_generer_liste_des_clients(frm) {
    console.log("▶ run_generer_liste_des_clients called");

    frm.call({
        doc: frm.doc,
        method: 'generer_liste_des_clients'
    }).then(() => {
        return frm.reload_doc();
    }).then(() => {
        frm.refresh_field('liste_des_clients');
        console.log("▶ liste_des_clients rafraîchie");
    });
}

function run_generer_liste_des_destinataires(frm) {
    console.log("▶ run_generer_liste_des_destinataires called");

    frm.call({
        doc: frm.doc,
        method: 'generer_liste_des_distinataires'
    }).then(() => {
        frm.refresh_field('liste_des_destinataires');
        frm.refresh_field('liste_des_clients');
        console.log("▶ liste_des_destinataires & liste_des_clients rafraîchies");
    });
}

frappe.ui.form.on('Compagne SMS', {
    refresh(frm) {
        const is_draft = frm.doc.docstatus === 0;

        // Bouton "Envoyer SMS" visible uniquement en brouillon et non nouveau doc
        frm.set_df_property('envoyer_sms', 'hidden', !(is_draft && !frm.is_new()));

        frm.toggle_enable(
            ['groupes_des_clients', 'liste_des_clients', 'liste_des_destinataires', 'message'],
            is_draft
        );

        // mettre à jour les compteurs au chargement du formulaire
        update_message_counters(frm);
    },

    // ✅ Cas fieldname SANS accents: generer_liste_des_clients
    generer_liste_des_clients(frm) {
        run_generer_liste_des_clients(frm);
    },

    // ✅ Cas fieldname AVEC accents: générer_liste_des_clients
    "générer_liste_des_clients"(frm) {
        run_generer_liste_des_clients(frm);
    },

    // Même logique pour "Générer liste des distinatataires"
    generer_liste_des_distinataires(frm) {
        run_generer_liste_des_destinataires(frm);
    },

    "générer_liste_des_distinataires"(frm) {
        run_generer_liste_des_destinataires(frm);
    },

    envoyer_sms(frm) {
        frappe.confirm(
            __('Voulez-vous vraiment lancer l’envoi des SMS ?'),
            () => {
                console.log("▶ envoyer_sms called");
                frm.call({
                    doc: frm.doc,
                    method: 'envoyer_sms'
                }).then(() => {
                    return frm.reload_doc();
                }).then(() => {
                    frm.refresh_field('liste_des_clients');
                    frm.refresh_field('liste_des_destinataires');
                    frm.refresh_field('nombre_total_compagne');
                    console.log("▶ Doc reloaded after envoyer_sms");
                });
            }
        );
    },

    // 🔥 Mise à jour LIVE des compteurs quand on tape le message
    message(frm) {
        update_message_counters(frm);
        // pas besoin de forcer frm.dirty(), Frappe le fait déjà quand on modifie un champ
    }
});
